const esc=value=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
export const createDraftImportState=()=>({phase:'idle',name:'',preview:null,clientKey:null,undoConfirm:false,error:''});
export function thesisDraftImportHTML(item,state,{busy=false}={}){
 const disabled=busy||['queued','running','cancelling'].includes(item?.job?.status),preview=state.preview,waiting=['uploading','reading'].includes(state.phase);
 return `<section class="thesis-draft-import" aria-label="上传已有初稿"><header><span class="thesis-draft-import-icon" aria-hidden="true">↥</span><div><h3>使用已有初稿</h3><p>上传你已经写好的 DOCX，识别章节后直接进入终稿完善。</p></div><span class="thesis-draft-import-format">DOCX · 最大 2MB</span></header><div class="thesis-action-row"><button type="button" class="btn secondary" data-draft-import-upload ${disabled?'disabled':''}>上传已有初稿</button><button type="button" class="btn secondary" data-draft-import-stored ${disabled?'disabled':''}>从文件管理选择</button><input type="file" accept=".docx" data-draft-import-file data-no-file-library hidden>${item?.importedDraft?`<button type="button" class="thesis-draft-import-undo" data-draft-import-undo ${disabled?'disabled':''}>撤销本次导入</button>`:''}</div>${waiting?`<div class="thesis-draft-import-progress" role="status" aria-live="polite" aria-busy="true"><span class="document-export-spinner" aria-hidden="true"></span><div><strong>${state.phase==='uploading'?'正在保存初稿…':'正在识别正文与章节…'}</strong><p>${esc(state.name)} · 识别完成后供你确认，尚未替换当前正文。</p></div></div>`:''}${state.error?`<p class="thesis-draft-import-error" role="alert">${esc(state.error)}</p>`:''}${preview?`<section class="thesis-draft-import-preview" aria-label="初稿识别结果"><div><h4>${esc(preview.name)}</h4><p>识别到 ${preview.chapters.length} 个章节 · ${Number(preview.characters).toLocaleString('zh-CN')} 字符 · ${preview.tableCount} 个普通表格 · ${preview.imageCount||0} 张图片 · ${preview.formulaCount||0} 个公式 · ${preview.referenceCount} 篇标准题录</p></div><ol tabindex="0" aria-label="已识别章节">${preview.chapters.map(row=>`<li><b>${esc(row.title)}</b><span>${Number(row.characters).toLocaleString('zh-CN')} 字符</span></li>`).join('')}</ol>${preview.warnings?.length?`<ul class="thesis-draft-import-warnings">${preview.warnings.map(text=>`<li>${esc(text)}</li>`).join('')}</ul>`:''}<p>${preview.replacesExisting?'确认后将使用上传初稿的章节与正文，原版本会保留，可撤销本次导入。':'确认后保存为当前论文的初稿，题目、已有研究资料和格式模板继续使用。'}导入不调用 AI、不扣写作积分。</p><div class="thesis-action-row"><button type="button" class="btn primary" data-draft-import-confirm ${disabled?'disabled':''}>导入并进入终稿撰写</button><button type="button" class="btn secondary" data-draft-import-cancel ${disabled?'disabled':''}>取消</button></div></section>`:''}${state.undoConfirm?`<section class="thesis-draft-import-preview" role="status"><strong>恢复导入前的正文与章节？</strong><p>当前导入内容仍保留在历史版本中；已有研究资料、封面与格式模板不会被删除。</p><div class="thesis-action-row"><button type="button" class="btn primary" data-draft-import-restore ${disabled?'disabled':''}>确认恢复导入前版本</button><button type="button" class="btn secondary" data-draft-import-cancel ${disabled?'disabled':''}>取消</button></div></section>`:''}<p class="thesis-draft-import-note">支持正文、章节、普通表格、已嵌入图片及 Word 公式；图片与公式会随正文保留到导出文档。</p></section>`;
}
export function bindThesisDraftImport(root,{upload,pick,confirm,cancel,undo,restore}={}){
 root?.querySelector('[data-draft-import-upload]')?.addEventListener('click',()=>root.querySelector('[data-draft-import-file]').click());
 root?.querySelector('[data-draft-import-file]')?.addEventListener('change',event=>{const file=event.target.files?.[0];if(file)upload(file);});
 for(const [name,action]of [['stored',pick],['confirm',confirm],['cancel',cancel],['undo',undo],['restore',restore]])root?.querySelector('[data-draft-import-'+name+']')?.addEventListener('click',()=>action?.());
}
